export const filePosStr = (h: TFilePos): string => {

	const {source, line, col} = h
	if (defined(source)) {
		const fileName = basename(source)
		return `${fileName}:${line}:${col}`
	}
	else {
		return `unknown:${line}:${col}`
	}
}

