export const sourceMapTable = (
		hSrcMap: TSourceMap,
		hOptions: hash = {}
		): string => {

	assert((hSrcMap.version === 3), "Not version 3")
	assert((hSrcMap.sources.length === 1), "Multiple sources")

	type opt = {
		linesOnly: boolean
		maxMaps: number
		}
	const {linesOnly, maxMaps} = getOptions<opt>(hOptions, {
		linesOnly: false,
		maxMaps: 10
		})

	const fmtStr = (linesOnly ? 'r r r' : 'r r r r r')
	const table = new TextTable(fmtStr, {decPlaces: 0})
	table.fullsep('=')
	table.title('lMappings')
	table.fullsep('=')
	const lMappings = (
		  defined(hSrcMap.lMappings)
		? hSrcMap.lMappings
		: getMappings(hSrcMap.mappings)
		)
	if (linesOnly) {
		table.labels( ['typescript', '=>', 'civet'])
		let prevLine = -1
		let numMaps = 0
		for (const item of lMappings) {
			const [line, col, iFile, iLine, iCol] = item
			if (line !== prevLine) {
				table.data([line, '=>', iLine])
				prevLine = line
				numMaps += 1
				if (numMaps >= maxMaps) {
					break
				}
			}
		}
	}
	else {
		table.labels( ['line', 'col', '=>', 'line', 'col'])
		let i1 = 0;for (const item of lMappings) {const i = i1++;
			if (i >= maxMaps) {
				break
			}
			const [line, col, iFile, iLine, iCol] = item
			table.data([line, col, '=>', iLine, iCol])
		}
	}
	table.fullsep('=')

	const {version, file, sources, names, sourceRoot} = hSrcMap
	const table2 = new TextTable('l l')
	table2.data(['version',    `${version}`])
	table2.data(['file',       `${file}`])
	table2.data(['sources',    `${sources}`])
	table2.data(['sourceRoot', `${sourceRoot || '<missing>'}`])

	return [
		table2.asString(),
		table.asString()
		].join('\n')
}

